import { useId, useMemo, useRef, useState } from 'react'
import { useVirtualizer } from '@tanstack/react-virtual'
import { CircleSlash2, ListRestart } from 'lucide-react'
import type { EvaluatedTrade, LiquidityRole } from '../domain/types'
import { useApp } from '../state/AppContext'
import { dateTime, money, number, percent, signedMoney } from '../utils/format'

type ExecutionSort = 'time-desc' | 'time-asc' | 'pnl-desc' | 'pnl-asc'
type ProfitFilter = 'all' | 'profit' | 'loss' | 'pending'
type RoleFilter = LiquidityRole | 'all'

interface ExecutionLedgerProps {
  trades: EvaluatedTrade[]
  ariaLabel: string
  initialSort?: ExecutionSort
  showEventName?: boolean
}

const comparePnl = (first: EvaluatedTrade, second: EvaluatedTrade, direction: 1 | -1) => {
  if (first.netPnl === null && second.netPnl === null) return Date.parse(second.originalDate) - Date.parse(first.originalDate)
  if (first.netPnl === null) return 1
  if (second.netPnl === null) return -1
  return (first.netPnl - second.netPnl) * direction
}

const contractAmount = (value: number) => number(value, Number.isInteger(value) ? 0 : 2)

export const ExecutionLedger = ({
  trades,
  ariaLabel,
  initialSort = 'time-desc',
  showEventName = true
}: ExecutionLedgerProps) => {
  const { friendlyNames, metadata } = useApp()
  const [sort, setSort] = useState<ExecutionSort>(initialSort)
  const [profitFilter, setProfitFilter] = useState<ProfitFilter>('all')
  const [roleFilter, setRoleFilter] = useState<RoleFilter>('all')
  const parentRef = useRef<HTMLDivElement>(null)
  const controlId = useId()
  const hasFilters = profitFilter !== 'all' || roleFilter !== 'all'

  const visibleTrades = useMemo(() => trades
    .filter(trade => roleFilter === 'all' || trade.orderType === roleFilter)
    .filter(trade => {
      if (profitFilter === 'profit') return trade.netPnl !== null && trade.netPnl > 0
      if (profitFilter === 'loss') return trade.netPnl !== null && trade.netPnl < 0
      if (profitFilter === 'pending') return trade.source === 'polymarket' ? (trade.openAmount ?? 0) > 0 || Boolean(trade.accountingWarning) : !trade.settled
      return true
    })
    .sort((first, second) => {
      if (sort === 'time-asc') return Date.parse(first.originalDate) - Date.parse(second.originalDate)
      if (sort === 'time-desc') return Date.parse(second.originalDate) - Date.parse(first.originalDate)
      if (sort === 'pnl-asc') return comparePnl(first, second, 1)
      return comparePnl(first, second, -1)
    }), [profitFilter, roleFilter, sort, trades])

  const virtualizer = useVirtualizer({
    count: visibleTrades.length,
    getScrollElement: () => parentRef.current,
    estimateSize: () => 112,
    overscan: 10
  })

  const resetFilters = () => {
    setProfitFilter('all')
    setRoleFilter('all')
  }

  return (
    <div className='execution-ledger'>
      <div className='execution-controls'>
        <div className='execution-controls__fields'>
          <label htmlFor={`${controlId}-sort`}>
            <span>Ordenar</span>
            <select
              id={`${controlId}-sort`}
              aria-label='Ordenar execuções'
              value={sort}
              onChange={event => setSort(event.target.value as ExecutionSort)}
            >
              <option value='time-desc'>Horário · mais recentes</option>
              <option value='time-asc'>Horário · mais antigas</option>
              <option value='pnl-desc'>Lucro · maior primeiro</option>
              <option value='pnl-asc'>Lucro · menor primeiro</option>
            </select>
          </label>
          <label htmlFor={`${controlId}-profit`}>
            <span>Resultado</span>
            <select
              id={`${controlId}-profit`}
              aria-label='Filtrar resultado das execuções'
              value={profitFilter}
              onChange={event => setProfitFilter(event.target.value as ProfitFilter)}
            >
              <option value='all'>Todos</option>
              <option value='profit'>Com lucro</option>
              <option value='loss'>Com prejuízo</option>
              <option value='pending'>Pendentes</option>
            </select>
          </label>
          <label htmlFor={`${controlId}-role`}>
            <span>Liquidez</span>
            <select
              id={`${controlId}-role`}
              aria-label='Filtrar liquidez das execuções'
              value={roleFilter}
              onChange={event => setRoleFilter(event.target.value as RoleFilter)}
            >
              <option value='all'>Todas</option>
              <option value='Maker'>Maker</option>
              <option value='Taker'>Taker</option>
              <option value='Unknown'>Não informada</option>
            </select>
          </label>
        </div>
        <div className='execution-controls__summary' aria-live='polite'>
          <span>{number(visibleTrades.length)} de {number(trades.length)} execuções</span>
          {hasFilters && <button className='execution-reset' type='button' onClick={resetFilters}><ListRestart size={15} aria-hidden='true' />Limpar filtros</button>}
        </div>
      </div>

      {visibleTrades.length ? (
        <div className='execution-table'>
          <div className='execution-table__head' aria-hidden='true'>
            <span>Mercado / horário</span>
            <span>Lado</span>
            <span>Contratos</span>
            <span>Entrada</span>
            <span>Custo</span>
            <span>Taxas</span>
            <span>Payout</span>
            <span>Retorno</span>
            <span>Liquidez</span>
          </div>
          <div className='execution-viewport' ref={parentRef} tabIndex={0} role='region' aria-label={ariaLabel}>
            <div className='execution-virtual' role='list' style={{ height: `${virtualizer.getTotalSize()}px` }}>
              {virtualizer.getVirtualItems().map(virtualRow => {
                const trade = visibleTrades[virtualRow.index]
                const eventName = friendlyNames[trade.eventTicker] ?? trade.eventTicker
                const market = metadata[trade.eventTicker]?.markets.find(item => item.ticker === trade.marketTicker)
                const marketName = showEventName ? eventName : market?.title || eventName
                const invested = (trade.realizedCost ?? trade.cost) + (trade.realizedFees ?? trade.fee)
                const roi = trade.netPnl === null || invested <= 0 ? null : trade.netPnl / invested
                const closedWithoutPnl = trade.netPnl === null && trade.openAmount === 0 && !trade.accountingWarning
                const resultClass = trade.netPnl === null ? closedWithoutPnl ? '' : 'pending' : trade.netPnl >= 0 ? 'positive' : 'negative'

                return (
                  <div
                    className='execution-row'
                    key={trade.id}
                    role='listitem'
                    data-index={virtualRow.index}
                    ref={virtualizer.measureElement}
                    style={{ transform: `translateY(${virtualRow.start}px)` }}
                  >
                    <div className='execution-market' data-label='Mercado / horário'>
                      <strong title={marketName}>{marketName}</strong>
                      <div className='execution-market__source'><code title={trade.marketTicker}>{trade.marketSlug || trade.marketTicker}</code><span className={`tag tag--${trade.source === 'polymarket' ? 'polymarket' : 'source'}`}>{trade.source === 'polymarket' ? 'POLYMARKET' : 'KALSHI'}</span></div>
                      {trade.accountName && <span className='execution-account' title={trade.accountId}>{trade.accountName}</span>}
                      <time dateTime={trade.originalDate}>{dateTime(trade.originalDate)}</time>
                    </div>
                    <div className='execution-side' data-label='Lado'><span className={`tag tag--${trade.direction.toLocaleLowerCase()}`} title={trade.outcome || trade.direction}>{trade.outcome || trade.direction}</span>{trade.side && <small>{trade.side === 'BUY' ? 'Compra' : 'Venda'}</small>}</div>
                    <div data-label='Contratos'>{contractAmount(trade.amount)}</div>
                    <div data-label='Entrada'>{number(trade.effectivePrice, 2)}¢</div>
                    <div data-label='Custo'>{money(trade.cost)}</div>
                    <div data-label='Taxas' title={trade.feesKnown === false ? 'Taxas não informadas pela API pública; o resultado não inclui essas taxas.' : undefined}>{trade.feesKnown === false ? '—' : money(trade.fee)}</div>
                    <div data-label='Payout'>{trade.payout === null ? '—' : money(trade.payout)}</div>
                    <div className={`execution-return ${resultClass}`} data-label='Retorno'>
                      <strong title={trade.accountingWarning}>{trade.netPnl === null ? closedWithoutPnl ? 'Encerrada' : 'Pendente' : signedMoney(trade.netPnl)}</strong>
                      {roi !== null && <span>{percent(roi, 1)}</span>}
                    </div>
                    <div data-label='Liquidez'><span className={`tag tag--${trade.orderType.toLocaleLowerCase()}`}>{trade.orderType === 'Unknown' ? 'N/D' : trade.orderType}</span></div>
                  </div>
                )
              })}
            </div>
          </div>
        </div>
      ) : (
        <div className='execution-empty'>
          <CircleSlash2 aria-hidden='true' />
          <strong>{trades.length ? 'Nenhuma execução corresponde aos filtros.' : 'Nenhuma execução neste recorte.'}</strong>
          {hasFilters && <button className='button button--ghost' type='button' onClick={resetFilters}>Mostrar todas</button>}
        </div>
      )}
    </div>
  )
}
